import React, { useState } from 'react';
import axios from 'axios';

function MalwareLab() {
  const [file, setFile] = useState(null);
  const [result, setResult] = useState(null);

  const upload = () => {
    const formData = new FormData();
    formData.append('file', file);
    axios.post('/api/malware/scan', formData, {headers:{'Content-Type':'multipart/form-data'}})
      .then(res => setResult(res.data))
      .catch(err => console.error(err));
  };

  return (
    <div>
      <h2>Malware Analysis Lab</h2>
      <input type="file" onChange={e=>setFile(e.target.files[0])} />
      <button onClick={upload} className="btn btn-primary">Scan</button>
      {result && (
        <div className="mt-3">
          <p>Name: {result.file_name}</p>
          <p>Size: {result.file_size}</p>
          <p>SHA256: {result.sha256}</p>
          <p>MD5: {result.md5}</p>
          <p>Status: {result.status}</p>
          <p>Entropy: {result.entropy}</p>
        </div>
      )}
    </div>
  );
}

export default MalwareLab;
